import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.BxrwG5q5.js";const g=JSON.parse('{"title":"Configuration Scopes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scopes.md","filePath":"guide/scopes.md"}'),i={name:"guide/scopes.md"};function o(r,e,l,c,p,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="configuration-scopes" tabindex="-1">Configuration Scopes <a class="header-anchor" href="#configuration-scopes" aria-label="Permalink to &quot;Configuration Scopes&quot;">​</a></h1><p>The config package supports multi-tenant, multi-project scoping. Each config definition declares a <code>scope</code> that determines how values are resolved.</p><h2 id="scope-types" tabindex="-1">Scope Types <a class="header-anchor" href="#scope-types" aria-label="Permalink to &quot;Scope Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>tenant</code></td><td>Scoped to a tenant organization</td></tr><tr><td><code>project</code></td><td>Scoped to a project within a tenant</td></tr><tr><td><code>environment</code></td><td>Scoped to an environment within a project</td></tr></tbody></table><h2 id="how-scoping-works" tabindex="-1">How Scoping Works <a class="header-anchor" href="#how-scoping-works" aria-label="Permalink to &quot;How Scoping Works&quot;">​</a></h2><p>Scoping allows you to manage configurations for multiple tenants (organizations) or projects from a single @jewel998/config deployment. Each API key is tied to a specific project and environment, which means:</p><ol><li>When the SDK makes a request, the <code>clientId</code> resolves to a specific <code>projectId</code> + <code>environmentId</code></li><li>Config values returned are already scoped to that combination</li><li>Different environments within the same project are fully independent</li></ol><h2 id="resolve-context" tabindex="-1">Resolve Context <a class="header-anchor" href="#resolve-context" aria-label="Permalink to &quot;Resolve Context&quot;">​</a></h2><p>When reading values, pass a <code>ConfigResolveContext</code> to scope the lookup:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getValue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;feature.beta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  tenantId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme-corp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  projectId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dashboard&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  environment: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;staging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The resolver checks scoped cache keys in priority order and returns the first match.</p><h2 id="fallback-chain" tabindex="-1">Fallback Chain <a class="header-anchor" href="#fallback-chain" aria-label="Permalink to &quot;Fallback Chain&quot;">​</a></h2><p>When resolving a config value, the system checks from most-specific to least-specific:</p><ol><li><strong>Environment scope</strong> — <code>feature.beta</code> in <code>acme-corp / dashboard / staging</code></li><li><strong>Project scope</strong> — <code>feature.beta</code> in <code>acme-corp / dashboard</code> (any environment)</li><li><strong>Tenant scope</strong> — <code>feature.beta</code> in <code>acme-corp</code> (any project)</li><li><strong>Default value</strong> — The flag&#39;s base value</li></ol><p>If a value is defined at the environment level, it takes precedence over project-level or tenant-level values.</p><h2 id="scoped-key-format" tabindex="-1">Scoped Key Format <a class="header-anchor" href="#scoped-key-format" aria-label="Permalink to &quot;Scoped Key Format&quot;">​</a></h2><p>Cache keys are built by combining the config key with scope identifiers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature.beta:tenant:acme-corp:project:dashboard:environment:staging</span></span></code></pre></div><p>This allows different tenants and projects to have independent configuration values stored in the same cache.</p><h2 id="relationship-with-environments" tabindex="-1">Relationship with Environments <a class="header-anchor" href="#relationship-with-environments" aria-label="Permalink to &quot;Relationship with Environments&quot;">​</a></h2><p>Scopes and environments work together:</p><ul><li><strong>Environments</strong> are the lowest-level scope — each has independent config values, API keys, and targeting rules</li><li><strong>Projects</strong> group environments (dev, staging, production) under one umbrella</li><li><strong>Tenants</strong> group projects for multi-tenant SaaS deployments</li></ul><p>In most single-tenant setups, you&#39;ll only interact with project and environment scopes through the portal&#39;s environment switcher. Tenant-level scoping becomes relevant when deploying a single @jewel998/config instance for multiple customer organizations.</p><h2 id="configuring-scopes" tabindex="-1">Configuring Scopes <a class="header-anchor" href="#configuring-scopes" aria-label="Permalink to &quot;Configuring Scopes&quot;">​</a></h2><p>Scopes are managed through the portal:</p><ol><li><strong>Tenant scope</strong> — Created when you set up multi-tenant mode in project settings</li><li><strong>Project scope</strong> — Each project is a scope boundary (create projects in the portal)</li><li><strong>Environment scope</strong> — Created within a project (dev, staging, prod)</li></ol><p>API keys always bind to a specific environment scope, ensuring complete data isolation between environments.</p>`,27)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
